import React from 'react';

const IASection = () => {
  const styles = {
    section: {
      // Léger dégradé similaire à la section témoignages
      background: 'linear-gradient(180deg, #F9F9F9 0%, #F4F4F4 100%)',
      padding: '90px 24px', fontFamily: 'Poppins, sans-serif'
    },
    container: { maxWidth: 1200, margin: '0 auto' },
    badge: { display: 'inline-block', background: '#FFF3ED', color: '#FF5A00', padding: '6px 14px', borderRadius: 20, fontSize: 12, fontWeight: 600, marginBottom: 16 },
    title: { fontSize: 34, fontWeight: 800, color: '#111', marginBottom: 16 },
    highlight: { color: '#FF5A00' },
    text: { fontSize: 15, color: '#666', lineHeight: 1.7, maxWidth: 650 }
  };

  return (
    <section id="ai" style={styles.section}>
      <div style={styles.container}>
        <div style={styles.badge}>Djamano IA</div>
        <h2 style={styles.title}>Une IA dédiée à vos <span style={styles.highlight}>Analyses</span></h2>
        <p style={styles.text}>
          Optimisez vos ventes de billets, anticipez les tendances de vos futurs événements et comprenez avec exactitude le comportement de vos participants grâce à notre modèle intelligent embarqué.
        </p>
      </div>
    </section>
  );
};

export default IASection;
